"""Responsive live dashboard for the Dragon arbitrage engine."""

HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#090b10"><title>Dragon | Live Control Room</title>
<style>
:root{--bg:#080a0f;--panel:#10141b;--panel2:#151b24;--line:#252d39;--text:#f4f6f8;--muted:#8995a5;--gold:#d3b15e;--green:#45d69a;--red:#ff6470;--amber:#f3be59;--blue:#67aaff}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -10%,#202a3d 0,#080a0f 43%);color:var(--text);font:14px Inter,system-ui,-apple-system,Segoe UI,sans-serif}main{max-width:1440px;margin:auto;padding:16px}.top{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}.brand{display:flex;align-items:center;gap:11px}.logo{width:46px;height:46px;border:1px solid #4a3e25;border-radius:14px;display:grid;place-items:center;color:var(--gold);font-size:25px;background:#0d1016}.title h1{margin:0;font-size:22px}.title p{margin:3px 0 0;color:var(--muted);font-size:12px}.live{border:1px solid #385d49;background:#0f1d17;color:var(--green);padding:8px 12px;border-radius:999px;font-weight:800}.live.off{border-color:#61343a;background:#1b1013;color:var(--red)}.hero{display:grid;grid-template-columns:1.55fr 1fr;gap:10px}.panel{background:linear-gradient(145deg,var(--panel),#0d1117);border:1px solid var(--line);border-radius:15px;padding:14px;box-shadow:0 10px 28px #0005}.section{margin-top:10px}.sectionhead{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px}.sectionhead h2{font-size:14px;margin:0}.badge{padding:4px 8px;border-radius:7px;background:#1a202a;color:var(--muted);font-size:10px}.statusgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.status{background:var(--panel2);border:1px solid var(--line);border-radius:11px;padding:10px}.status b{display:block;font-size:12px}.status span{display:block;color:var(--muted);font-size:10px;margin-top:4px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px;background:var(--red)}.ok .dot{background:var(--green);box-shadow:0 0 10px #45d69a}.warn .dot{background:var(--amber)}.pnl{font-size:32px;font-weight:850;margin:4px 0}.gold{color:var(--gold)}.negative{color:var(--red)}.muted{color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-top:10px}.metric{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:11px}.metric .label{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.07em}.metric .num{font-size:21px;font-weight:800;margin-top:4px}.split{display:grid;grid-template-columns:1fr 1fr;gap:10px}.diagrow{display:grid;grid-template-columns:150px 1fr 70px;align-items:center;gap:8px;font-size:11px;padding:2px 0}.bar{height:8px;background:#202630;border-radius:99px;overflow:hidden}.fill{height:100%;width:0;background:var(--gold);border-radius:99px}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:11px;white-space:nowrap}th,td{text-align:left;padding:8px 7px;border-bottom:1px solid #202630}th{color:var(--muted);font-weight:600;position:sticky;top:0;background:var(--panel)}.edgegood{color:var(--green);font-weight:800}.edgebad{color:var(--red);font-weight:700}.fresh{color:var(--green)}.stale{color:var(--amber)}.events{max-height:300px;overflow:auto}.event{display:grid;grid-template-columns:78px 125px 1fr;gap:8px;padding:8px 0;border-bottom:1px solid #202630;font-size:11px}.event .kind{font-weight:800}.event .msg{color:#c5ccd6}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.warnbox{background:#2b2108;border:1px solid #80671b;padding:9px 11px;border-radius:10px;margin-top:7px;font-size:11px}.errorbox{background:#2b1115;border:1px solid #71343d;padding:9px 11px;border-radius:10px;margin-top:7px;font-size:11px}.footer{margin-top:10px;color:var(--muted);font-size:10px;text-align:center}
@media(max-width:1050px){.metrics{grid-template-columns:repeat(3,1fr)}}@media(max-width:800px){.hero,.split{grid-template-columns:1fr}.statusgrid{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}.top{align-items:flex-start}.event{grid-template-columns:65px 95px 1fr}.diagrow{grid-template-columns:120px 1fr 55px}}
</style></head><body><main>
<div class="top"><div class="brand"><div class="logo">🐉</div><div class="title"><h1>Dragon Live Control Room</h1><p>Binance Spot triangular arbitrage • execution, market quality & opportunity telemetry</p></div></div><div id="mode" class="live">● CONNECTING</div></div>
<div id="alerts"></div>
<div class="hero"><section class="panel"><div class="sectionhead"><h2>Execution status</h2><span id="age" class="badge">updating</span></div><div class="statusgrid"><div id="ws" class="status"><b><i class="dot"></i>Market WebSocket</b><span>Binance market feed</span></div><div id="api" class="status"><b><i class="dot"></i>Binance API</b><span>Authenticated account access</span></div><div id="engine" class="status"><b><i class="dot"></i>Engine</b><span>Scanner and executor</span></div></div><div class="section"><div class="muted">Realized P&amp;L</div><div id="pnl" class="pnl gold">0.000000 USDT</div><div class="muted">Available USDT <b id="bal">0</b> • Dynamic taker fee <b id="fee">0.00 bps</b> • Uptime <b id="uptime">--</b></div></div></section>
<section class="panel"><div class="sectionhead"><h2>Execution intelligence</h2><span class="badge">LIVE TELEMETRY</span></div><div class="diagrow"><span>Net edge threshold</span><span class="mono" id="edge">--</span><span></span></div><div class="diagrow"><span>Execution latency</span><span class="mono" id="lat">0 ms</span><span></span></div><div class="diagrow"><span>Last opportunity</span><span class="mono" id="lastopp">none</span><span></span></div><div class="diagrow"><span>Last execution</span><span class="mono" id="lastexec">none</span><span></span></div><div class="diagrow"><span>Reconnects / disconnects</span><span class="mono" id="reconnects">0 / 0</span><span></span></div><div class="diagrow"><span>Last error</span><span id="lasterror" class="mono">none</span><span></span></div></section></div>
<div class="metrics"><div class="metric"><div class="label">Triangles</div><div class="num" id="tri">0</div></div><div class="metric"><div class="label">Symbols</div><div class="num" id="sym">0</div></div><div class="metric"><div class="label">Market streams</div><div class="num" id="streams">0</div></div><div class="metric"><div class="label">Quote updates</div><div class="num" id="quotes">0</div></div><div class="metric"><div class="label">Depth updates</div><div class="num" id="depth">0</div></div><div class="metric"><div class="label">Scans</div><div class="num" id="scans">0</div></div><div class="metric"><div class="label">Opportunities</div><div class="num" id="opp">0</div></div><div class="metric"><div class="label">Executions</div><div class="num" id="exec">0</div></div><div class="metric"><div class="label">Filled cycles</div><div class="num" id="filled">0</div></div><div class="metric"><div class="label">Execution errors</div><div class="num" id="errors">0</div></div><div class="metric"><div class="label">Risk blocks</div><div class="num" id="blocks">0</div></div><div class="metric"><div class="label">Min-notional blocks</div><div class="num" id="minblocks">0</div></div></div>
<div class="split section"><section class="panel"><div class="sectionhead"><h2>Decision funnel</h2><span id="rejtotal" class="badge">0 decisions</span></div><div id="bars"></div></section><section class="panel"><div class="sectionhead"><h2>Account & runtime health</h2><span class="badge">LIVE</span></div><div class="diagrow"><span>Balance refreshes</span><b id="refresh">0</b><span></span></div><div class="diagrow"><span>Circuit breaker trips</span><b id="circuit">0</b><span></span></div><div class="diagrow"><span>Subscription ACKs</span><b id="acks">0</b><span></span></div><div class="diagrow"><span>WS shards</span><span id="shards">0</span><span></span></div><div class="diagrow"><span>WS shard size</span><span id="shardsize">0</span><span></span></div><div class="diagrow"><span>External updates</span><span id="extupdates">0</span><span></span></div></section></div>
<section class="panel section"><div class="sectionhead"><h2>🏆 Best live triangle opportunities</h2><span class="badge">ranked by net edge</span></div><div id="opps" class="tablewrap"><span class="muted">Waiting for market data...</span></div></section>
<section class="panel section"><div class="sectionhead"><h2>🌐 Cross-exchange opportunity monitor</h2><span class="badge">observation only • no external execution</span></div><div id="cross" class="tablewrap"><span class="muted">Waiting for synchronized quotes...</span></div></section>
<section class="panel section"><div class="sectionhead"><h2>🌍 External feed health</h2><span class="badge">BYBIT • OKX • COINBASE</span></div><div id="external"><span class="muted">Waiting for external market data...</span></div></section>
<section class="panel section"><div class="sectionhead"><h2>📡 Live event stream</h2><span class="badge">last 100 • refresh 2s</span></div><div id="events" class="events"><div class="muted">Waiting for engine events...</div></div></section>
<div class="footer">Dragon dashboard • telemetry is observational and never bypasses Binance exchange filters, fees, slippage, stale-data checks, or execution controls.</div>
</main><script>
const $=id=>document.getElementById(id);const esc=x=>String(x??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m]));const fmt=n=>Number(n||0).toLocaleString(undefined,{maximumFractionDigits:3});const ts=t=>t?new Date(Number(t)*1000).toLocaleTimeString():'none';
function setStatus(id,ok,label){const e=$(id);e.className='status '+(ok?'ok':'');e.querySelector('b').innerHTML='<i class="dot"></i>'+label}
function age(t){if(!t)return '--';let a=Math.max(0,Date.now()/1000-Number(t));return a<60?a.toFixed(1)+'s':Math.floor(a/60)+'m'}
function render(s){
 setStatus('ws',!!s.ws_connected,'Market WebSocket');setStatus('api',!!s.binance_authenticated,'Binance API');setStatus('engine',s.status==='running','Engine');
 const live=!!s.live&&!s.dry_run;$('mode').textContent=live?'● LIVE EXECUTION':'● SAFE / PAPER';$('mode').className='live '+(live?'':'off');
 const pnl=Number(s.realized_pnl_usdt||0);$('pnl').textContent=pnl.toFixed(6)+' USDT';$('pnl').className='pnl '+(pnl>=0?'gold':'negative');$('bal').textContent=esc(s.free_usdt||'0');$('fee').textContent=Number(s.dynamic_fee_bps||0).toFixed(2)+' bps';$('uptime').textContent=s.started_at?age(s.started_at):'--';
 [['tri','triangles'],['sym','symbols'],['streams','market_streams'],['quotes','quote_updates'],['depth','depth_updates'],['scans','scans'],['opp','opportunities'],['exec','executions'],['filled','ledger_filled'],['errors','execution_errors'],['blocks','risk_blocks'],['minblocks','min_notional_blocks'],['refresh','balance_refreshes'],['circuit','circuit_breaker_trips'],['acks','subscription_acks'],['shards','ws_shards'],['shardsize','ws_shard_size'],['extupdates','external_feed_updates']].forEach(([a,b])=>$(a).textContent=fmt(s[b]));
 $('edge').textContent=(s.min_net_edge_bps??'--')+' bps';$('lat').textContent=(s.last_execution_latency_ms??0)+' ms';$('lastopp').textContent=ts(s.last_opportunity);$('lastexec').textContent=ts(s.last_execution);$('reconnects').textContent=fmt(s.ws_reconnects)+' / '+fmt(s.ws_disconnects);$('lasterror').textContent=esc(s.last_error||'none');$('age').textContent='updated '+new Date().toLocaleTimeString();
 const alerts=[];(s.warnings||[]).forEach(w=>alerts.push('<div class="warnbox">⚠️ '+esc(w)+'</div>'));if(s.last_error)alerts.push('<div class="errorbox">⛔ Last engine error: '+esc(s.last_error)+'</div>');$('alerts').innerHTML=alerts.join('');
 const rej=s.rejection||{},total=Number(s.rejection_total||0);$('rejtotal').textContent=fmt(total)+' decisions';const keys=['NO_LIQUIDITY','STALE','FEE_REJECTED','SLIPPAGE_REJECTED','NET_EDGE_REJECTED','NET_EDGE_PASSED'];const max=Math.max(1,...keys.map(k=>Number(rej[k]||0)));$('bars').innerHTML=keys.map(k=>{let v=Number(rej[k]||0);return '<div class="diagrow"><span>'+k.replaceAll('_',' ')+'</span><div class="bar"><div class="fill" style="width:'+((v/max)*100).toFixed(1)+'%"></div></div><span>'+fmt(v)+'</span></div>'}).join('');
 const o=(s.top_opportunities||[]).slice().sort((a,b)=>Number(b.net_bps||0)-Number(a.net_bps||0));$('opps').innerHTML=o.length?'<table><tr><th>#</th><th>Triangle</th><th>Gross</th><th>Net</th><th>Eval notional</th><th>Budget</th><th>Eligible</th><th>Age</th></tr>'+o.map((x,i)=>{let n=Number(x.net_bps||0),ok=!!x.eligible;return '<tr><td>'+(i+1)+'</td><td class="mono">'+esc(Array.isArray(x.path)?x.path.join(' → '):x.path)+'</td><td>'+Number(x.gross_bps||0).toFixed(3)+' bps</td><td class="'+(n>=Number(s.min_net_edge_bps||0)?'edgegood':'edgebad')+'">'+n.toFixed(3)+' bps</td><td>'+esc(x.evaluation_notional)+'</td><td>'+esc(x.trade_budget??'0')+'</td><td class="'+(ok?'edgegood':'edgebad')+'">'+(ok?'YES':'NO')+'</td><td>'+age(x.ts)+'</td></tr>'}).join('')+'</table>':'<span class="muted">No ranked triangle opportunities yet.</span>';
 const c=s.cross_exchange_opportunities||[];$('cross').innerHTML=c.length?'<table><tr><th>Symbol</th><th>Buy venue</th><th>Sell venue</th><th>Gross edge</th><th>Buy ask</th><th>Sell bid</th><th>Size</th><th>Age</th></tr>'+c.map(x=>'<tr><td class="mono">'+esc(x.symbol)+'</td><td>'+esc(x.buy)+'</td><td>'+esc(x.sell)+'</td><td class="edgegood">'+Number(x.gross_bps||0).toFixed(3)+' bps</td><td>'+Number(x.buy_ask||0).toFixed(8)+'</td><td>'+Number(x.sell_bid||0).toFixed(8)+'</td><td>'+esc(x.size_base??'--')+'</td><td class="'+(Number(age(x.ts).replace('s',''))<3?'fresh':'stale')+'">'+age(x.ts)+'</td></tr>').join('')+'</table>':'<span class="muted">No synchronized cross-exchange candidate currently visible.</span>';
 const feeds=s.external_feeds||{};$('external').innerHTML=['BYBIT','OKX','COINBASE'].map(v=>{let f=feeds[v]||{},a=f.last_update?Math.max(0,Date.now()/1000-Number(f.last_update)):999;let good=f.status==='connected'&&a<5;return '<div class="diagrow"><span><b>'+v+'</b></span><span class="'+(good?'fresh':'stale')+'">● '+esc(f.status||'unknown')+' &nbsp; updates='+esc(f.updates||0)+' &nbsp; age='+a.toFixed(1)+'s'+(f.reconnects?' &nbsp; reconnects='+f.reconnects:'')+(f.last_error?' &nbsp; error='+esc(f.last_error):'')+'</span><span></span></div>'}).join('');
 const ev=(s.recent||[]).slice().reverse();$('events').innerHTML=ev.length?ev.map(e=>'<div class="event"><span class="muted">'+ts(e.ts)+'</span><span class="kind">'+esc(e.kind||'EVENT')+'</span><span class="msg">'+esc(e.message||'')+(e.path?' <span class="mono">['+esc(Array.isArray(e.path)?e.path.join(' → '):e.path)+']</span>':'')+(e.net_bps!=null?' <b>'+Number(e.net_bps).toFixed(3)+' bps</b>':'')+'</span></div>').join(''):'<div class="muted">Waiting for engine events...</div>';
}
async function tick(){try{const r=await fetch('/health?ts='+Date.now(),{cache:'no-store'});const j=await r.json();render(j.state||{})}catch(e){$('mode').textContent='● DASHBOARD ERROR';$('mode').className='live off';$('alerts').innerHTML='<div class="errorbox">⛔ Dashboard health endpoint unavailable.</div>'}}tick();setInterval(tick,2000);
</script></body></html>'''
